    "author": "Targum Onkelos",
    "text": "Și au zis: „Haideți să ne zidim o cetate și un turn al cărui vârf să ajungă până la înălțimea cerurilor, și să ne facem un nume, ca nu cumva să ne risipim pe fața întregului pământ.”"
