    "text": "«Haideți să ne construim un oraș și un turn.» Înalt la vedere, cu vârful în ceruri, adică foarte înalt, ca în „cetăți mari și fortificate până la ceruri”.<br><br>«Și să ne facem un nume.» Ca numele turnului și al orașului să iasă departe, căci dacă vom merge într-o țară depărtată, vom ști să ne întoarcem aici; oricine va fi întrebat de drum va ști, căci toți vor vorbi despre el; și îl vom vedea și de departe.<br><br>«Ca nu cumva să fim împrăștiați pe fața întregului pământ.» Și au căutat să anuleze ceea ce hotărâse Sfântul: „și umpleți pământul și supuneți-l”."
