    "author": "Fericitul Augustin, Despre cetatea lui Dumnezeu",
    "text": "Cetatea aceasta numită „Încurcătură” nu era alta decât Babilonul, a cărui zidire minunată o dovedesc mărturiile istoriei păgâne. Căci Babilon înseamnă „încurcătură”. Se pare că întemeietorul cetății a fost uriașul Nimrod, după cum s-a observat mai sus. Pomenindu-l, Scriptura ne spune că Babilonul a fost capul regatului lui, adică în fruntea tuturor celorlalte cetăți, capitala în care își avea scaunul stăpânirea regatului. Totuși cetatea n-a ajuns niciodată la desăvârșirea la care visase mândria oamenilor nelegiuiți. Planul cerea o înălțime uriașă: avea să ajungă la cer. Poate că aceasta privește unul dintre turnurile ei, care trebuia să fie mai înalt decât toate celelalte, sau poate cuvântul „turn” înseamnă toate turnurile, cum „cal” poate însemna mii de călăreți."
