  "fidela": "Și Sem a trăit, după ce a născut pe Arpacșad, cinci sute de ani; și a născut fii și fiice.",
  "commentaries": [
   {
    "author": "Targum Onkelos",
    "text": "Și Sem a trăit, după ce l-a născut pe Arpacșad, cinci sute de ani; și a născut fii și fiice."
   },
   {
    "author": "Targum Ionatan",
    "text": "Și a trăit Sem, după ce l-a născut pe Arpacșad, cinci sute de ani și a născut fii și fiice."
   },
   {
    "author": "Sforno (cca. 1475–1550)",
    "text": "«Și i s-au născut fii și fiice.» Nu a amintit la niciunul din aceste zece generații «și a murit», cum a amintit la acele zece generații de la Adam până la Noe; căci aceia au murit toți înainte de a fi subiectul povestirii urmărite atunci, adică potopul. Dar aceștia erau toți vii în vremea în care a început subiectul povestirii urmărite aici, adică strădania lui Avraam, părintele nostru, mai mult decât a tuturor drepților generațiilor de dinaintea lui, de a chema Numele Domnului, ca să facă cunoscute oamenilor faptele Lui puternice și slava strălucirii domniei Lui, și să-i atragă cu funiile iubirii de bunătate, ca să-L slujească umăr la umăr."
   },
   {
    "author": "Chizkuni (sec. XIII)",
    "text": "«Și a mai trăit Sem cinci sute de ani.» Dar „și au fost toate zilele lui” nu s-a spus, cum s-a spus la cele zece generații de la Adam până la Noe, pentru că toate zilele generațiilor dintâi au fost multe, aproape o mie de ani; dar după potop s-au micșorat, precum este scris „i-ai purtat ca un torent, un an să fie”. Și s-au micșorat până la șaptezeci și, dacă prin puteri, optzeci de ani; de aceea nu s-a îngrijit să le însumeze „toate zilele lor”.<br><br>«Și i s-au născut fii și fiice.» După potop, când lumea s-a umplut de fii ai omului și a fost zidit scrisul la ei: „și i s-au născut fii și fiice”; și tot așa la David, care a lăsat un fiu mare, este scris la el „adormire”, dar Ioab, care nu a lăsat un fiu atât de mare, este scris la el „moarte”."
   }
  ],
