    "author": "Chizkuni (sec. XIII)",
    "text": "«Tatăl Iscăi.» Rashi: „Aceasta este Sarai.” Trebuie spus că Haran a născut-o pe Sara la șase ani, după calculul numelor lor, și așa este în mod explicit în Bereșit Rabba. Și am aflat în capitolul „Fiul îndărătnic și răzvrătit” că generațiile dintâi, fiecare dintre ei la opt ani zămislea, și tot așa de la Bețaleel și de la Bat-Șeba și de la Er și Onan."
