    "text": "Și Terah l-a luat pe Avram, fiul său, și pe Lot, fiul lui Haran, fiul fiului său, și pe Sarai, nora sa, soția lui Avram, fiul său; și au ieșit împreună din Ur al caldeenilor ca să meargă în țara Canaan; și au ajuns până la Haran și s-au așezat acolo."
