    "dict_ro": "Terah moare în Haran la două sute cinci ani, adică în anul 2083 de la creație (în Septuaginta, 3449). Pentateuhul Samaritean are aici o sută patruzeci și cinci de ani, deci anul 2324: după această cifră Terah moare exact când Avram, născut la 70 de ani ai lui Terah, are 75 de ani, vârsta plecării din Haran (12:4); în ebraică și în Septuaginta, Terah ar mai fi trăit încă 60 de ani după plecarea lui Avram."
